try:
    def _date(a):
        import re
        a = str(a).strip()
        if re.match(r'^\d{4}-\d{2}-\d{2}', a):
            return a[:10]
        mon = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec']
        low = a.lower().replace(',', ' ')
        y = mo = dy = None
        m = re.match(r'^(\d{1,2})\s*[./\- ]\s*(\d{1,2})\s*[./\- ]\s*(\d{4})$', low)
        if m:
            dy, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            for w in re.findall(r'[a-z]+', low):
                if len(w) >= 3 and w[:3] in mon:
                    mo = mon.index(w[:3]) + 1
            ym = re.search(r'(\d{4})', low)
            dm = re.search(r'(?<!\d)(\d{1,2})(?:st|nd|rd|th)?(?!\d)', low)
            if ym:
                y = int(ym.group(1))
            if dm:
                dy = int(dm.group(1))
        if y and mo and dy:
            return '%04d-%02d-%02d' % (y, mo, dy)
        return a
    def _digits(a):
        import re
        d = re.sub(r'\D', '', str(a))
        return d if d else str(a)
    def _time(a):
        import re
        m = re.match(r'^(\d{1,2})[:.h](\d{2})', str(a).strip())
        return ('%02d:%02d' % (int(m.group(1)), int(m.group(2)))) if m else a
    _b = config.get('body')
    if isinstance(_b, dict):
        for _k in list(_b.keys()):
            _x = _b.get(_k)
            if _k not in ['date', 'time'] and (_x is None or str(_x).strip().lower() in ('', 'none', 'null') or '{' in str(_x)):
                _b.pop(_k, None)
        for _f, _v, _drop in []:
            if str(_b.get(_f)) == str(_v):
                for _k in _drop:
                    _b.pop(_k, None)
        _kind = dict([]).get(str(_b.get('')))
        if _kind == 'date' and '' in _b:
            _b[''] = _date(_b[''])
        if _kind == 'digits' and '' in _b:
            _b[''] = _digits(_b[''])
        for _k in ['date']:
            if isinstance(_b.get(_k), str):
                _b[_k] = _date(_b[_k])
        for _k in ['time']:
            if isinstance(_b.get(_k), str):
                _b[_k] = _time(_b[_k])
        for _k in []:
            if isinstance(_b.get(_k), str):
                try:
                    _b[_k] = float(_b[_k].replace(',', ''))
                except Exception:
                    pass
        _ids = [x for x in str(vars.get('product_ids') or '').split(',') if x]
        if 'product_id' in _b and len(_ids) == 1:
            _b['product_id'] = _ids[0]
except Exception:
    pass

